import {rasterStroke} from './raster.js';
import {layerState} from './folders.js';
import {command} from './model.js';
export const wandLimits=Object.freeze({pixels:1024*1024,dimension:1024});
const fail=m=>{throw Error(m);};
export function validateSnapshot(s){if(!s||!Number.isInteger(s.width)||!Number.isInteger(s.height)||s.width<1||s.height<1||s.width>1024||s.height>1024||s.width*s.height>wandLimits.pixels||!Number.isInteger(s.x)||!Number.isInteger(s.y)||Math.max(Math.abs(s.x),Math.abs(s.y),Math.abs(s.x+s.width),Math.abs(s.y+s.height))>1e7||!(s.data instanceof Uint8ClampedArray)||s.data.length!==s.width*s.height*4)fail('Invalid wand pixel surface');return s;}
export function selectPixels(s,x,y,{tolerance=12,contiguous=true}={}){
 validateSnapshot(s);if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||y<0||x>=s.width||y>=s.height)fail('Tap within the bounded layer pixels');if(!Number.isFinite(tolerance)||tolerance<0||tolerance>100||typeof contiguous!=='boolean')fail('Invalid wand settings');
 const n=s.width*s.height,mask=new Uint8Array(n),seed=(y*s.width+x)*4,d=s.data,alpha=d[seed+3],target=[d[seed]*alpha/255,d[seed+1]*alpha/255,d[seed+2]*alpha/255,alpha],threshold=tolerance*255/100;let inspected=0;
 const matches=i=>{inspected++;const p=i*4,a=d[p+3];return Math.max(Math.abs(a-target[3]),Math.abs(d[p]*a/255-target[0]),Math.abs(d[p+1]*a/255-target[1]),Math.abs(d[p+2]*a/255-target[2]))<=threshold;};
 if(!contiguous){for(let i=0;i<n;i++)if(matches(i))mask[i]=1;}else{const seen=new Uint8Array(n),queue=new Int32Array(n);let head=0,tail=0;const visit=i=>{if(seen[i])return;seen[i]=1;if(matches(i)){mask[i]=1;queue[tail++]=i;}};visit(y*s.width+x);while(head<tail){const i=queue[head++],xx=i%s.width;if(xx)visit(i-1);if(xx+1<s.width)visit(i+1);if(i>=s.width)visit(i-s.width);if(i+s.width<n)visit(i+s.width);}}
 return {mask,inspected};
}
export function combineMasks(previous,next,mode='replace'){if(!(next instanceof Uint8Array)||next.length>wandLimits.pixels||!['replace','add','subtract'].includes(mode)||previous!==null&&(!(previous instanceof Uint8Array)||previous.length!==next.length)||next.some(v=>v>1)||previous?.some(v=>v>1))fail('Invalid wand selection mask');const out=new Uint8Array(next.length);for(let i=0;i<out.length;i++)out[i]=mode==='replace'?next[i]:mode==='add'?(previous?.[i]||next[i]):(previous?.[i]&&!next[i]?1:0);return out;}
export function regionBounds(s,mask){validateSnapshot(s);if(!(mask instanceof Uint8Array)||mask.length!==s.width*s.height||mask.some(v=>v>1))fail('Invalid wand selection mask');let minX=s.width,minY=s.height,maxX=0,maxY=0,count=0;for(let i=0;i<mask.length;i++)if(mask[i]){const x=i%s.width,y=Math.floor(i/s.width);minX=Math.min(minX,x);minY=Math.min(minY,y);maxX=Math.max(maxX,x+1);maxY=Math.max(maxY,y+1);count++;}return count?{minX:minX+s.x,minY:minY+s.y,maxX:maxX+s.x,maxY:maxY+s.y,width:maxX-minX,height:maxY-minY,cx:s.x+(minX+maxX)/2,cy:s.y+(minY+maxY)/2,count}:null;}
export function splitPixels(s,mask){const bounds=regionBounds(s,mask);if(!bounds)fail('No pixels selected');const selected=new Uint8ClampedArray(bounds.width*bounds.height*4),rest=new Uint8ClampedArray(s.data);let pigment=false,remaining=false;for(let i=0;i<mask.length;i++){if(mask[i]){const x=i%s.width+s.x-bounds.minX,y=Math.floor(i/s.width)+s.y-bounds.minY,o=(y*bounds.width+x)*4;for(let k=0;k<4;k++)selected[o+k]=s.data[i*4+k];if(s.data[i*4+3])pigment=true;rest.fill(0,i*4,i*4+4);}else if(s.data[i*4+3])remaining=true;}return {bounds,pigment,selected:rasterStroke(selected,bounds.width,bounds.height,bounds.minX,bounds.minY),remaining:remaining?rasterStroke(rest,s.width,s.height,s.x,s.y):null};}
function checkRegion(h,r){if(!r||h.board!==r.board)fail('Pixel selection is stale');const l=h.board.layers.find(l=>l.id===r.layerId);if(!l)fail('Selection layer missing');const state=layerState(h.board,l);if(state.locked||!state.visible)fail('Selection layer is locked or hidden');return l;}
export function regionClipboard(h,r){checkRegion(h,r);const split=splitPixels(r.snapshot,r.mask);if(!split.pigment)fail('Selected region has no pigment to copy');return {version:1,strokes:[split.selected],bounds:split.bounds};}
function regionRemainder(r,split){return r.remainingFactory?r.remainingFactory():split.remaining?[split.remaining]:[];}
export function deleteRegion(h,r){checkRegion(h,r);const split=splitPixels(r.snapshot,r.mask);if(!split.pigment)return h;const remaining=regionRemainder(r,split);return command(h,b=>{b.version=Math.max(4,b.version);b.layers.find(l=>l.id===r.layerId).strokes=remaining;});}
export function prepareRegionTransform(h,r){checkRegion(h,r);const split=splitPixels(r.snapshot,r.mask);if(!split.pigment)fail('Selected region has no pigment to transform');const remaining=regionRemainder(r,split);const working=command(h,b=>{b.version=Math.max(4,b.version);b.layers.find(l=>l.id===r.layerId).strokes=[...remaining,split.selected];});return {working,id:split.selected.id};}
export function commitRegionTransform(h,r,preview){checkRegion(h,r);return command(h,b=>{b.version=Math.max(4,b.version);b.layers.find(l=>l.id===r.layerId).strokes=structuredClone(preview.board.layers.find(l=>l.id===r.layerId).strokes);});}
